  const PDFJS_WORKER_PADRAO = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.worker.min.js';
  const PDFJS_WORKER_ALT = 'https://unpkg.com/pdfjs-dist@2.16.105/build/pdf.worker.min.js';
  const PDFJS_TIMEOUT_MS = 20000;
  const PDFJS_TENTATIVAS = 2;

